starter.css:
form { display: grid; gap: 6px; max-width: 320px; }
input:not([type="radio"]) { font: inherit; padding: 6px 8px; border: 1px solid #77708f; border-radius: 6px; }
fieldset { border: 1px solid #c9c4dc; border-radius: 8px; padding: 8px 12px; }
.error { color: #b3261e; margin: 0; }
[aria-invalid="true"] { border-color: #b3261e; border-width: 2px; }
button { justify-self: start; font: inherit; padding: 8px 16px; border-radius: 8px; border: 0; background: #5b3cc4; color: #fff; }

