const email = document.querySelector('#email');
const error = document.querySelector('#email-error');

// The playground blocks real form submission, so validation runs on the
// submit button's click. That click also fires when Enter is pressed in a field.
document.querySelector('#pay').addEventListener('click', (event) => {
  event.preventDefault();
  if (email.value.includes('@')) {
    error.hidden = true;
    return;
  }
  error.textContent = 'Enter an email address like name@example.com';
  error.hidden = false;
});

